    DURATION,
    DISTANCE,
    AVG_PACE,
    AVG_SPEED,
    ELEVATION_GAIN,
    AVG_HEART_RATE,
    MAX_HEART_RATE,
    AVG_CADENCE,
    AVG_POWER,
    CALORIES,
    EFFORT,
    NOTE,
}

